
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_sg4_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_sg4", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.947516528315935e-02, -5.840629747669575e-02, -5.687339735361331e-02, -5.467789895461213e-02, -5.153994434896340e-02, -4.707206803588032e-02, -4.076475581212797e-02, -3.206615743052423e-02, -2.093016290421021e-02, -1.000917594960487e-02, -8.339288649650127e-03, -3.153685669087394e-02, -4.234535099084177e-02, -2.433705659282805e-02, -8.427700735350816e-03, -4.245832532310083e-03, -8.424860435129151e-03, -8.177847590198829e-03, -2.295605187484643e-03, -3.268687243322624e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


